"""TokenGuard - LLM API 429 Prevention Engine"""

import time
from dataclasses import dataclass
from typing import Dict, List, Optional, Tuple


@dataclass
class Decision:
    """Result of a pre-flight check."""
    action: str  # proceed, wait, fallback, block
    estimated_tokens: int
    wait_seconds: float
    fallback_model: Optional[str]
    reason: str


class TokenGuard:
    """Prevents LLM API 429 errors through smart rate limiting."""

    MODEL_QUOTAS = {
        'gemini-3-flash': 1_000_000,
        'gemini-3-pro': 2_000_000,
        'claude-haiku': 50_000,
        'claude-sonnet': 200_000,
        'claude-opus': 200_000,
        'gpt-4o': 800_000,
        'deepseek': 1_000_000,
    }

    FALLBACK_ORDER = ['gemini-3-flash', 'deepseek', 'claude-haiku']

    def __init__(self):
        self._usage: Dict[str, List[Tuple[float, int]]] = {}
        self._duplicates: Dict[str, List[float]] = {}
        self._cache: Dict[str, str] = {}
        self._retry_delays: Dict[str, float] = {}
        self._stats = {
            'total_checks': 0,
            'tokens_saved': 0,
            'blocks': 0,
            'fallbacks': 0,
        }

    def _get_current_time(self) -> float:
        return time.time()

    def _estimate_tokens(self, prompt: str) -> int:
        """CJK-aware token estimation."""
        tokens = 0
        for char in prompt:
            # CJK characters count as 2 tokens
            if (\u4e00 <= char <= \u9fff or  # CJK Unified Ideographs
                \u3400 <= char <= \u4dbf or  # CJK Extension A
                \u20000 <= char <= \u2a6df or  # CJK Extension B
                \u3040 <= char <= \u309f or  # Hiragana
                \u30a0 <= char <= \u30ff or  # Katakana
                \uac00 <= char <= \ud7af or  # Hangul Syllables
                \u1100 <= char <= \u11ff):  # Hangul Jamo
                tokens += 2
            else:
                tokens += 1
        return max(1, tokens)

    def _get_usage_in_window(self, model: str, window: float = 60.0) -> int:
        """Get tokens used in the last window seconds."""
        now = self._get_current_time()
        cutoff = now - window
        if model not in self._usage:
            return 0
        return sum(tokens for ts, tokens in self._usage[model] if ts > cutoff)

    def _clean_old_records(self, window: float = 60.0):
        """Remove records older than window seconds."""
        now = self._get_current_time()
        cutoff = now - window
        for model in self._usage:
            self._usage[model] = [(ts, t) for ts, t in self._usage[model] if ts > cutoff]
        for prompt in self._duplicates:
            self._duplicates[prompt] = [ts for ts in self._duplicates[prompt] if ts > cutoff]

    def check(self, prompt: str, model: str) -> Decision:
        """Pre-flight check before making an API call."""
        self._stats['total_checks'] += 1
        self._clean_old_records()

        estimated_tokens = self._estimate_tokens(prompt)

        # Track duplicates
        if prompt not in self._duplicates:
            self._duplicates[prompt] = []
        self._duplicates[prompt].append(self._get_current_time())
        duplicate_count = len(self._duplicates[prompt])

        # Duplicate detection: block if 3+ times in 60s
        if duplicate_count >= 3:
            self._stats['blocks'] += 1
            self._stats['tokens_saved'] += estimated_tokens
            return Decision(
                action='block',
                estimated_tokens=estimated_tokens,
                wait_seconds=0,
                fallback_model=None,
                reason=f'Duplicate request detected ({duplicate_count} times in 60s)',
            )

        # Get model quota (use default if unknown)
        tpm_limit = self.MODEL_QUOTAS.get(model, 1_000_000)
        usage = self._get_usage_in_window(model)
        usage_pct = (usage / tpm_limit) * 100

        # Block at >95% quota
        if usage_pct > 95:
            self._stats['blocks'] += 1
            self._stats['tokens_saved'] += estimated_tokens
            return Decision(
                action='block',
                estimated_tokens=estimated_tokens,
                wait_seconds=0,
                fallback_model=None,
                reason=f'Model quota exceeded ({usage_pct:.1f}%)',
            )

        # Wait at >80% quota
        if usage_pct > 80:
            # Calculate wait time for window to slide enough
            needed_tokens = tpm_limit * 0.8 - usage
            if needed_tokens > 0:
                # Wait until enough tokens are freed (simplified: wait 1 second)
                wait_time = 1.0
            else:
                wait_time = 0.1
            return Decision(
                action='wait',
                estimated_tokens=estimated_tokens,
                wait_seconds=wait_time,
                fallback_model=None,
                reason=f'Approaching quota limit ({usage_pct:.1f}%)',
            )

        # Check for cached response
        if prompt in self._cache:
            return Decision(
                action='proceed',
                estimated_tokens=estimated_tokens,
                wait_seconds=0,
                fallback_model=None,
                reason='Cached response available',
            )

        # Find fallback model if primary is getting close
        fallback = None
        for fb_model in self.FALLBACK_ORDER:
            if fb_model == model:
                continue
            fb_limit = self.MODEL_QUOTAS.get(fb_model, 1_000_000)
            fb_usage = self._get_usage_in_window(fb_model)
            fb_pct = (fb_usage / fb_limit) * 100
            if fb_pct < 80:
                fallback = fb_model
                break

        return Decision(
            action='proceed',
            estimated_tokens=estimated_tokens,
            wait_seconds=0,
            fallback_model=fallback,
            reason='Request approved',
        )

    def record_usage(self, tokens: int, model: str):
        """Record token usage for a model."""
        if model not in self._usage:
            self._usage[model] = []
        self._usage[model].append((self._get_current_time(), tokens))

    def cache_response(self, prompt: str, response: str):
        """Cache a successful response."""
        self._cache[prompt] = response

    def record_429(self, model: str, retry_delay: float):
        """Record a 429 error with retry delay."""
        self._retry_delays[model] = retry_delay

    def status(self) -> dict:
        """Get current status of all models and stats."""
        self._clean_old_records()
        models = {}
        for model, tpm_limit in self.MODEL_QUOTAS.items():
            usage = self._get_usage_in_window(model)
            remaining = tpm_limit - usage
            usage_pct = (usage / tpm_limit) * 100
            if usage_pct < 80:
                status = 'OK'
            elif usage_pct < 95:
                status = 'WARNING'
            else:
                status = 'BLOCKED'
            models[model] = {
                'tpm_limit': tpm_limit,
                'used_this_minute': usage,
                'remaining': remaining,
                'usage_pct': f'{usage_pct:.1f}%',
                'status': status,
            }
        return {
            'models': models,
            'stats': self._stats,
        }
